import {readFile,writeFile,mkdir,copyFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {spawn} from 'node:child_process';
import {once} from 'node:events';
import {resolve,join} from 'node:path';
const selected=process.argv[2]==='inventory'?'postgres-h6-008-inventory.test.ts':'postgres-h6-008-independent.test.ts';
const root=resolve(import.meta.dirname,'..'),folder=join(root,'tests/fixtures/h6-auth-independent-review');
const hash=b=>createHash('sha256').update(b).digest('hex');
const run=join(folder,'contraprobes-'+new Date().toISOString().replace(/[:.]/g,'-'));
await mkdir(run);
const expected=await readFile(join(folder,'independent-expected.json'));
const source=await readFile(join(root,'tests/integration/'+selected));
await writeFile(join(run,'expected.json'),expected);await writeFile(join(run,'test-source.ts'),source);
const env={PATH:process.env.PATH,HOME:process.env.HOME,TMPDIR:'/tmp/crm-h6-local-'+hash(root).slice(0,12),LANG:'C',LC_ALL:'C',POSTGRES_H0_BIN:'/Users/andres/Applications/Postgres.app/Contents/Versions/17/bin',NODE_NO_WARNINGS:'1',CI:'1',H5008_CAPTURE_DIR:join(run,'observations'),H5009_CAPTURE_DIR:join(run,'observations')};
await mkdir(env.H5008_CAPTURE_DIR);
const record={startedAt:new Date().toISOString(),expectedSha256:hash(expected),testSourceSha256:hash(source),baseCommit:'971c55d5ce5770c71284d106d3c0deecca9514b5',candidateManifestSha256:'b674ac9ac035371fd2175a0ac22744f6c60c1b0f58b7538cb0d9af2e30d1d3b5'};
const child=spawn(process.execPath,['scripts/test-postgres.mjs',selected],{cwd:root,env,stdio:['ignore','pipe','pipe']});let stdout='',stderr='';
child.stdout.on('data',b=>stdout+=b);child.stderr.on('data',b=>stderr+=b);
const [exitCode,signal]=await once(child,'exit');
await writeFile(join(run,'stdout.log'),stdout);await writeFile(join(run,'stderr.log'),stderr);
Object.assign(record,{finishedAt:new Date().toISOString(),exitCode,signal,stdoutSha256:hash(stdout),stderrSha256:hash(stderr)});
await writeFile(join(run,'run.json'),JSON.stringify(record,null,2)+'\n');
console.log(JSON.stringify({run,exitCode,summary:stdout.split('\n').filter(x=>/^[✖✔ℹ]/.test(x)),stderr:stderr.slice(-1500)},null,2));process.exitCode=exitCode??1;
